INSERT INTO `failure_analyses` (`item_id`, `tanggal`, `equip_no`, `component_name`, `chronology`, `five_why_json`, `fishbone_json`, `corrective_action`, `preventive_action`, `status`, `lead_investigator`, `created_at`, `updated_at`) VALUES
('FAR-2026-001', '2026-09-02', 'DZ-007', 'TRANSMISSION TORQFLOW', 'Saat operasi dozing overburden, unit DZ-007 tidak dapat bergerak maju/mundur. Tekanan torqflow terukur di bawah standar 17 kg/cm² yaitu hanya 9 kg/cm². Unit dinyatakan breakdown dan WO-001 dibuka.', '{"w1":"Unit tidak dapat bergerak karena torqflow tidak membangun tekanan.","w2":"Pressure control valve torqflow macet dan tidak berfungsi.","w3":"Kontaminasi metal debris pada circuit oli transmisi menyebabkan valve seret.","w4":"Filter transmisi tidak diganti sesuai jadwal interval 250H karena stok kosong.","root_cause":"Manajemen stok filter transmisi tidak terpantau; minimun stok tidak dijaga sehingga PM tidak bisa dilaksanakan tepat waktu."}', '{"man":"PMC tidak memonitor ketersediaan sparepart filter transmisi sebelum jadwal PM.","machine":"Torqflow DZ-007 usia pakai 11.840 jam - komponen sudah mendekati batas lifetime.","material":"Kualitas oli transmisi tidak dicek sejak 500 jam terakhir.","method":"Prosedur monitoring tekanan torqflow tidak ada dalam form P2H harian.","environment":"Unit beroperasi di area berdebu tinggi yang mempercepat kontaminasi oli."}', 'Bersihkan circuit transmisi, ganti filter dan oli transmisi, setting ulang pressure control valve.', 'Tambahkan item cek tekanan torqflow pada form P2H harian. Pastikan stok filter transmisi minimum 3 PC selalu tersedia di gudang.', 'IN PROGRESS', 'Hariadi', '2026-09-13 08:00:00', '2026-09-13 08:00:00'),
('FAR-2026-002', '2026-09-03', 'WL-019', 'MAIN HYDRAULIC PUMP', 'Gerakan bucket WL-019 terasa lambat dan tekanan hidrolik rendah di bawah 250 bar dari standar 320 bar. Pressure test menunjukkan main pump mengalami internal leakage.', '{"w1":"Tekanan hidrolik rendah menyebabkan gerakan bucket lambat dan tidak bertenaga.","w2":"Main hydraulic pump mengalami internal leakage dan tidak dapat membangun pressure.","w3":"Piston pump aus akibat kontaminasi partikel besi pada oli hidrolik.","w4":"Filter return line hidrolik tidak diganti pada PM 500H terakhir.","root_cause":"Prosedur PM 500H WL-019 tidak lengkap; penggantian filter return line terlewat menyebabkan kontaminasi oli dan kerusakan pump."}', '{"man":"Mekanik melewatkan item penggantian filter return line saat PM 500H.","machine":"Main pump WL-019 usia pakai 3.950 jam - komponen dalam periode rawan kerusakan.","material":"Oli hidrolik terkontaminasi partikel besi dari keausan komponen.","method":"Checklist PM 500H tidak mencantumkan verifikasi kondisi oli dengan analisis.","environment":"Unit beroperasi di area loading berbatu yang mempercepat getaran komponen."}', 'Overhaul main hydraulic pump, ganti seal kit dan piston set, flush system hidrolik, ganti oli dan semua filter.', 'Tambahkan oil analysis hidrolik pada PM 500H. Buat checklist verifikasi tekanan pompa setelah setiap PM.', 'IN PROGRESS', 'Andi Herwan', '2026-09-13 08:00:00', '2026-09-13 08:00:00'),
('FAR-2026-003', '2026-09-06', 'GST-003', 'ALTERNATOR', 'Genset GST-003 mati total saat operasi malam hari karena tegangan drop dari 28V ke 18V. Alternator ditemukan gosong pada rotor coil.', '{"w1":"Genset mati karena alternator tidak mengisi baterai sehingga tegangan drop.","w2":"Rotor coil alternator short circuit dan terbakar.","w3":"Suhu internal alternator overheat akibat debu batubara menyumbat ventilasi.","w4":"Blowing debu pada housing alternator tidak dilakukan saat servis PM.","root_cause":"Prosedur cleaning alternator belum masuk checklist mandatory servis PM 500H genset."}', '{"man":"Mekanik tidak melakukan blowing debu pada kompartemen alternator saat PM.","machine":"Alternator GST-003 usia pakai 4.920 jam tanpa penggantian.","material":"Rotor coil kualitas standar rentan terhadap kontaminasi debu batubara.","method":"Checklist PM genset tidak mencantumkan cleaning alternator secara spesifik.","environment":"Lokasi genset di area stockpile berdebu tebal 24 jam."}', 'Ganti alternator baru P/N VG1500090065. Periksa wiring harness dan koneksi charging.', 'Tambahkan item mandatory Blowing & Cleaning Alternator pada checklist PM genset. Lakukan inspeksi visual alternator setiap 250 jam.', 'CLOSED', 'Hariadi', '2026-09-13 08:00:00', '2026-09-13 08:00:00');
