('NOTULEN-001', '2026-09-04', 'Evaluasi Kesiapan Alat (PA) & Pengendalian Breakdown Mingguan', 'Hariadi', 'Andi Herwan, Brayen, M. Nur Salam, M. Rahim', 'Pembahasan target PA armada PT. KUK area KBCT/LMP. Disepakati percepatan sparepart untuk DZ-007, WL-016, dan WL-019 yang berstatus BREAKDOWN.', '[{"item":"Follow up sparepart brake WL-016","pic":"Brayen","deadline":"2026-09-02","status":"IN PROGRESS"},{"item":"Siapkan special tool untuk transmission DZ-007","pic":"Andi Herwan","deadline":"2026-09-01","status":"IN PROGRESS"},{"item":"Evaluasi hydraulic pump WL-019","pic":"Hariadi","deadline":"2026-09-01","status":"IN PROGRESS"}]', 'ACTIVE', 'PA Armada 85.2% dari target 88% - 3 unit BREAKDOWN', 'DZ-007 transmission torqflow kritis - menghambat produksi overburden', 'Kapasitas hauling berkurang ±15% selama DZ-007 & WL-016 tidak operasi', 'Prioritaskan sparepart DZ-007 & WL-016, percepat overhaul transmission', '2026-09-13 08:00:00', '2026-09-13 08:00:00'),
('NOTULEN-002', '2026-09-07', 'Weekly Maintenance Review & Target PA September 2026', 'Hariadi', 'Andi Herwan, Brayen, M. Rahim, Tim Mekanik KBCT', 'Review progress WO minggu lalu: 8 CLOSED, 5 OPEN, 2 WAITING PART. PA sementara 85.5% dari target 88%.', '[{"item":"Selesaikan WO-007 (WL-019 hydraulic pump)","pic":"Tim Mekanik KBCT","deadline":"2026-09-08","status":"IN PROGRESS"},{"item":"Order bucket teeth untuk DT-3019","pic":"Brayen","deadline":"2026-09-09","status":"OPEN"},{"item":"Diagnosa final drive DZ-010 di area LMP","pic":"Andi Herwan","deadline":"2026-09-08","status":"IN PROGRESS"}]', 'ACTIVE', 'PA Armada 85.5% - target akhir bulan 88% masih achievable', 'WL-019 hydraulic pump perlu overhaul - downtime estimasi 3 hari', 'Produktivitas loading berkurang saat WL-019 off; EX-302 cover operasi sementara', 'Approve PO sparepart minggu depan; push vendor untuk delivery cepat', '2026-09-13 08:00:00', '2026-09-13 08:00:00');
